// Turns 722 review rows into ONE text block for step 2a.
// One line per review: [review_id] ★rating | title | text
const rows = $input.all().map(i => i.json);
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();

const lines = rows.map(r =>
  `[${r.review_id}] ★${r.rating} | ${clean(r.title)} | ${clean(r.text)}`
);

return [{ json: { review_count: rows.length, reviews_block: lines.join('\n') } }];

// 2b · MAKE BATCHES — groups UNTAGGED reviews into batches of 25 (one item per batch).
// Re-running the workflow only picks up reviews that still have no theme,
// so any review a batch missed is retried automatically on the next run.
const SIZE = 25;
const TEST_LIMIT = 0;   // ← 1 = test with ONE batch only. Set to 0 to run ALL batches.

const frozen = $('Frozen themes').first().json;
const rows = $('Data Table').all().map(i => i.json).filter(r => !r.theme);
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();

const themesText =
  frozen.themes.map(t =>
    `${t.id} ${t.name}: ${t.definition} Not included: ${t.not_included} Sub-themes: ` +
    Object.entries(t.sub_themes).map(([k, v]) => `${k} ${v}`).join('; ')
  ).join('\n') +
  `\nPraise: ${frozen.buckets.Praise}\nOther: ${frozen.buckets.Other}\n` +
  `Tie-break rules:\n- ${frozen.tie_break.join('\n- ')}`;

const batches = [];
for (let i = 0; i < rows.length; i += SIZE) {
  const b = rows.slice(i, i + SIZE);
  batches.push({ json: {
    batch_no: batches.length + 1,
    themes_version: frozen.themes_version,
    review_ids: b.map(r => String(r.review_id)),
    themes_text: themesText,
    reviews_text: b.map(r => `[${r.review_id}] ★${r.rating} | ${clean(r.title)} | ${clean(r.text)}`).join('\n'),
  }});
}
return TEST_LIMIT ? batches.slice(0, TEST_LIMIT) : batches;

const batches = $('Make batches').all().map(i => i.json);
const frozen = $('Frozen themes').first().json;
const validThemes = new Set([...frozen.themes.map(t => t.id), 'Praise', 'Other']);
const subsOf = Object.fromEntries(frozen.themes.map(t => [t.id, new Set(Object.keys(t.sub_themes))]));

// NEW: ID → readable name, built from the frozen list (never from the AI)
const themeName = Object.fromEntries([...frozen.themes.map(t => [t.id, t.name]), ['Praise', 'Praise'], ['Other', 'Other']]);
const subName = Object.fromEntries(frozen.themes.flatMap(t => Object.entries(t.sub_themes)));

const getText = j => j.output?.[0]?.content?.[0]?.text ?? j.text ?? j.message?.content ?? j.content ?? '';
const out = []; const report = [];

$input.all().forEach((item, idx) => {
  const batch = batches[idx]; const expected = new Set(batch.review_ids);
  let tags = [], problem = '';
  try { const parsed = JSON.parse(getText(item.json)); tags = Array.isArray(parsed) ? parsed : (parsed.tags ?? []); }
  catch (e) { problem = 'AI output was not valid JSON'; }
  const seen = new Set();
  for (const t of tags) {
    const id = String(t.review_id ?? '').trim();
    if (!expected.has(id) || seen.has(id)) continue;
    if (!validThemes.has(t.theme)) continue;
    seen.add(id);
    const sub = subsOf[t.theme]?.has(t.sub_theme) ? t.sub_theme : '';
    const fr = String(t.fee_related ?? '').toLowerCase().trim();
    const fee = fr.startsWith('i') ? 'issue' : fr.startsWith('m') ? 'mention' : 'no';
    out.push({ json: {
      review_id: id,
      theme: t.theme,
      theme_name: themeName[t.theme],                 // NEW
      sub_theme: sub,
      sub_theme_name: sub ? subName[sub] : '',        // NEW
      praise_topic: t.theme === 'Praise' ? String(t.praise_topic ?? '').slice(0, 40) : '',
      fee_related: fee,
      fee_type: fee === 'issue' ? String(t.fee_type ?? '').slice(0, 60) : '',
      language: String(t.language ?? '').slice(0, 5).toLowerCase(),
      tagged_with: batch.themes_version,
      batch_no: batch.batch_no
    }});
  }
  report.push({ batch: batch.batch_no, expected: expected.size, tagged: seen.size, missing: expected.size - seen.size, problem });
});
console.log('2b batch report', JSON.stringify(report));
return out;

// 2c · RANK THEMES — pure logic (no AI). Reads ALL tagged reviews, returns ONE summary item.
// Pain points per review: 1★=4, 2★=3, 3★=2, 4★=1, 5★=0. Ranks T1–T5 by total pain.
const frozen = $('Frozen themes').first().json;
const rows = $('Load tagged reviews').all().map(i => i.json);
const pain = r => Math.max(0, 5 - Number(r.rating || 0));
const themeIds = frozen.themes.map(t => t.id);
const tagged = rows.filter(r => r.theme);
const round = (x, d = 1) => Math.round(x * 10 ** d) / 10 ** d;

// ---------- 1. Theme + sub-theme ranking ----------
const themes = frozen.themes.map(t => {
  const rs = tagged.filter(r => r.theme === t.id);
  const subs = Object.entries(t.sub_themes).map(([sid, sname]) => {
    const srs = rs.filter(r => r.sub_theme === sid);
    return { id: sid, name: sname, reviews: srs.length, pain_points: srs.reduce((a, r) => a + pain(r), 0) };
  }).sort((a, b) => b.pain_points - a.pain_points);
  return {
    id: t.id, name: t.name, definition: t.definition,
    reviews: rs.length,
    negative_reviews: rs.filter(r => Number(r.rating) <= 2).length,
    avg_rating: rs.length ? round(rs.reduce((a, r) => a + Number(r.rating), 0) / rs.length, 2) : null,
    pain_points: rs.reduce((a, r) => a + pain(r), 0),
    sub_themes: subs,
  };
});
const totalPain = themes.reduce((a, t) => a + t.pain_points, 0) || 1;
themes.sort((a, b) => b.pain_points - a.pain_points)
  .forEach((t, i) => { t.rank = i + 1; t.top3 = i < 3; t.share_of_pain_pct = round(100 * t.pain_points / totalPain); });

// ---------- 2. Trend: Google Play only (B-lite) ----------
const dates = tagged.map(r => r.date).filter(Boolean).sort();
const end = new Date(dates[dates.length - 1]);
const recentStart = new Date(end); recentStart.setDate(end.getDate() - 27);
const rs0 = recentStart.toISOString().slice(0, 10);
const play = tagged.filter(r => r.source === 'google_play' && themeIds.includes(r.theme));
const playRecent = play.filter(r => r.date >= rs0), playPrev = play.filter(r => r.date < rs0);
const sumPain = arr => arr.reduce((a, r) => a + pain(r), 0) || 1;
const pPrev = sumPain(playPrev), pRecent = sumPain(playRecent);
const playDates = play.map(r => r.date).sort();
const trend = themes.map(t => {
  const prevRows = playPrev.filter(r => r.theme === t.id), recRows = playRecent.filter(r => r.theme === t.id);
  const prevShare = 100 * prevRows.reduce((a, r) => a + pain(r), 0) / pPrev;
  const recShare = 100 * recRows.reduce((a, r) => a + pain(r), 0) / pRecent;
  const change = recShare - prevShare;
  const direction = (recRows.length < 10 || prevRows.length < 10) ? 'not enough data'
                  : change >= 5 ? 'rising' : change <= -5 ? 'falling' : 'steady';
  return { id: t.id, name: t.name, prev_share_pct: round(prevShare), recent_share_pct: round(recShare),
           change_pts: round(change), prev_reviews: prevRows.length, recent_reviews: recRows.length, direction };
});

// ---------- 3. Praise, coverage (light eval), fees, by source ----------
const praise = tagged.filter(r => r.theme === 'Praise');
const praiseTopics = Object.entries(praise.reduce((m, r) => {
  const k = String(r.praise_topic || 'unspecified').toLowerCase().trim(); m[k] = (m[k] || 0) + 1; return m; }, {}))
  .sort((a, b) => b[1] - a[1]).slice(0, 5).map(([topic, reviews]) => ({ topic, reviews }));
const other = tagged.filter(r => r.theme === 'Other').length;
const nonPraise = tagged.length - praise.length;
const otherRate = nonPraise ? round(100 * other / nonPraise) : 0;
const bySource = {};
for (const r of tagged) { (bySource[r.source] ??= {}); bySource[r.source][r.theme] = (bySource[r.source][r.theme] || 0) + 1; }

return [{ json: {
  themes_version: frozen.themes_version,
  window: { start: dates[0], end: dates[dates.length - 1] },
  themes_ranked: themes,
  top3: themes.filter(t => t.top3).map(t => ({ id: t.id, name: t.name, pain_points: t.pain_points, reviews: t.reviews, share_of_pain_pct: t.share_of_pain_pct })),
  trend_google_play: {
    note: 'Google Play only: the one source with enough reviews in both periods.',
    previous_period: `${playDates[0]} to ${playPrev.length ? playPrev.map(r => r.date).sort().pop() : '-'}`,
    recent_period: `${rs0} to ${playRecent.length ? playRecent.map(r => r.date).sort().pop() : '-'} (Play data ends here)`,
    by_theme: trend,
  },
  praise: { reviews: praise.length, share_pct: round(100 * praise.length / (tagged.length || 1)), top_topics: praiseTopics },
  coverage_eval: {
    total_reviews: rows.length, tagged: tagged.length, untagged: rows.length - tagged.length,
    praise: praise.length, other,
    other_rate_excl_praise_pct: otherRate, pass_mark_pct: 20, pass: otherRate <= 20,
  },
  fees: {
    issue: tagged.filter(r => r.fee_related === 'issue').length,
    mention: tagged.filter(r => r.fee_related === 'mention').length,
  },
  by_source: bySource,
}}];

// 2d-i · QUOTE SHORTLIST — pure logic (no AI).
// Decision (14 Oct): "strongest quote, from where the theme mostly lives" + freshness = newest first, date shown.
// For each top-3 theme:
//   1. dominant source(s) = source with most reviews in that theme; any source within 25% of it also counts (near-tie)
//   2. candidates = biggest sub-theme · dominant source(s) · English · 1–2★ · 12–250 words · NEWEST FIRST
//   3. fallbacks only if fewer than 6: other sub-themes (dominant sources) → any source → 3★
const rank = $('Rank themes').first().json;
const rows = $('Load tagged reviews').all().map(i => i.json);
const MAX_PER_THEME = 6;
const NEAR_TIE = 0.75;                       // 2nd source counts as dominant if it has ≥75% of the top source's reviews
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();
const words = s => clean(s).split(' ').filter(Boolean).length;
const newestFirst = (a, b) => String(b.date).localeCompare(String(a.date));
const SOURCE_LABEL = { google_play: 'Google Play', app_store: 'App Store', trustpilot: 'Trustpilot' };

// newest first; if several sources, alternate between them so the AI sees both
const newestMixed = list => {
  const bySrc = {};
  for (const r of list) (bySrc[r.source] ??= []).push(r);
  const queues = Object.values(bySrc).map(a => a.sort(newestFirst));
  const out = [];
  while (queues.some(q => q.length)) for (const q of queues) if (q.length) out.push(q.shift());
  return out;
};

const themes = rank.themes_ranked.filter(t => t.top3).map(t => {
  const topSub = t.sub_themes[0];                                         // biggest-pain sub-theme (from 2c)
  const srcCounts = Object.entries(rank.by_source)
    .map(([src, counts]) => [src, counts[t.id] || 0]).sort((a, b) => b[1] - a[1]);
  const dominant = srcCounts.filter(([, n]) => n > 0 && n >= NEAR_TIE * srcCounts[0][1]).map(([s]) => s);

  const pool = rows.filter(r => r.theme === t.id && r.language === 'en'
                             && words(r.text) >= 12 && words(r.text) <= 250);
  const neg = r => Number(r.rating) <= 2;
  const tiers = [
    pool.filter(r => r.sub_theme === topSub.id && dominant.includes(r.source) && neg(r)),  // 1st choice
    pool.filter(r => r.sub_theme !== topSub.id && dominant.includes(r.source) && neg(r)),  // fallback 1
    pool.filter(r => r.sub_theme === topSub.id && !dominant.includes(r.source) && neg(r)), // fallback 2
    pool.filter(r => Number(r.rating) === 3 && dominant.includes(r.source)),               // fallback 3
  ];
  const picked = [];
  tiers.forEach((tier, i) => {
    for (const r of newestMixed(tier)) {
      if (picked.length >= MAX_PER_THEME) break;
      if (!picked.some(p => p.review_id === r.review_id)) picked.push({ ...r, tier: i });
    }
  });

  return {
    theme_id: t.id, theme_name: t.name,
    top_sub_theme: topSub.name,
    dominant_sources: dominant.map(s => SOURCE_LABEL[s] || s),
    candidates: picked.map(r => ({
      review_id: String(r.review_id), source: SOURCE_LABEL[r.source] || r.source,
      rating: Number(r.rating), date: r.date, sub_theme_name: r.sub_theme_name,
      used_fallback: r.tier > 0, text: clean(r.text),
    })),
  };
});

// one text block for the AI prompt
const candidates_text = themes.map(t =>
  `## ${t.theme_id} · ${t.theme_name} — biggest sub-theme: ${t.top_sub_theme}\n` +
  t.candidates.map(c => `[${c.review_id}] ${c.source} · ${c.rating}★ · ${c.date} · ${c.sub_theme_name}\n${c.text}`).join('\n\n')
).join('\n\n');

return [{ json: {
  themes,
  candidates_text,
  shortlist_check: themes.map(t => ({
    theme: t.theme_name, dominant_sources: t.dominant_sources, candidates: t.candidates.length,
    newest: t.candidates[0]?.date, oldest: t.candidates.at(-1)?.date,
    fallbacks_used: t.candidates.filter(c => c.used_fallback).length,
  })),
}}];

// 2d-iii · CHECK QUOTES — pure logic. Verifies every AI quote against the real review.
// Rules checked: review is in that theme's shortlist · one continuous piece, word for word ·
// "…" only at the edges · 6–30 words · no emails / ticket-style numbers.
// If a quote fails, a safe fallback is cut by code from the same review (or the top candidate),
// and it's flagged so the approver sees it.
const short = $('Quote shortlist').first().json;
const j = $input.first().json;
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let ai = [];
try { const p = JSON.parse(getText(j)); ai = Array.isArray(p) ? p : (p.quotes ?? []); } catch (e) { ai = []; }

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const monthLabel = d => { const [y, m] = String(d).split('-'); return `${MONTHS[Number(m) - 1]} ${y}`; };
const norm = s => String(s ?? '').replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"')
                                 .replace(/\s+/g, ' ').trim().toLowerCase();
const stripEdges = s => String(s ?? '').trim().replace(/^(\u2026|\.\.\.)\s*/, '').replace(/\s*(\u2026|\.\.\.)$/, '').trim();
const wordCount = s => stripEdges(s).split(/\s+/).filter(Boolean).length;
const PII = /[\w.+-]+@[\w-]+\.[\w.]+|#\s?\d{4,}|\d{6,}/;          // emails, #1234-style refs, long numbers

// fallback: first sentence of the review, cut to 30 words — always verbatim
const fallbackQuote = text => {
  const first = (text.match(/^.*?[.!?](\s|$)/) || [text])[0].trim();
  const w = first.split(/\s+/);
  const cut = w.length > 30 ? w.slice(0, 30).join(' ') : first;
  return cut + ((w.length > 30 || cut.length < text.trim().length) ? '…' : '');
};

const quotes = short.themes.map(t => {
  const a = ai.find(q => String(q.theme_id).trim() === t.theme_id) || {};
  const problems = [];
  let cand = t.candidates.find(c => c.review_id === String(a.review_id ?? '').trim());
  if (!a.quote) problems.push('AI gave no quote for this theme');
  if (!cand) problems.push('review_id not in this theme\'s shortlist');
  const core = stripEdges(a.quote);
  if (cand && a.quote) {
    if (/(\u2026|\.\.\.)/.test(core)) problems.push('"…" in the middle (stitched quote)');
    else if (!norm(cand.text).includes(norm(core))) problems.push('not word-for-word in the review');
    const wc = wordCount(a.quote);
    if (wc < 6 || wc > 30) problems.push(`length ${wc} words (allowed 6–30)`);
    if (PII.test(core)) problems.push('contains an email or ticket/order number');
  }
  let quote = a.quote, fallback = false;
  if (problems.length) {                       // safe fallback, clearly flagged
    cand = cand || t.candidates[0];
    quote = fallbackQuote(cand.text);
    fallback = true;
  }
  return {
    theme_id: t.theme_id, theme_name: t.theme_name, sub_theme: t.top_sub_theme,
    review_id: cand.review_id, source: cand.source, rating: cand.rating, date: cand.date,
    quote,
    attribution: `(${cand.source}, ${cand.rating}★, ${monthLabel(cand.date)})`,
    why: fallback ? '' : String(a.why ?? ''),
    status: fallback ? 'FALLBACK — check before approving' : 'verified',
    problems,
  };
});

return [{ json: {
  quotes,
  quotes_check: {
    verified: quotes.filter(q => q.status === 'verified').length,
    fallback: quotes.filter(q => q.status !== 'verified').length,
    all_verified: quotes.every(q => q.status === 'verified'),
  },
}}];

const FEE_GROUPS = {
  F1: { name: 'Charged after cancelling or unable to cancel', description: 'Users were billed after cancelling, or could not find how to cancel and stop recurring charges.' },
  F2: { name: 'Refund refused or not offered', description: 'Users asked for money or credits back for a charge and were refused or got no answer.' },
  F3: { name: 'Double or unexpected charges', description: 'Users saw a duplicate, unauthorised, auto-upgraded or otherwise unexpected charge.' },
  F4: { name: 'Paid but plan not active or access lost', description: 'Users paid but the paid plan did not activate, or paid access disappeared.' },
  F5: { name: 'Payment failed or card declined', description: 'Users could not pay or renew because the payment failed or the card was declined.' },
  F6: { name: 'Tax, currency or invoice confusion', description: 'Users were confused by taxes, currency conversion, invoice dates or billing details.' },
};
const rows = $('Load tagged reviews').all().map(i => i.json);
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();
const cap = (s, n) => { const w = clean(s).split(' '); return w.length > n ? w.slice(0, n).join(' ') + ' …' : clean(s); };
const feeAll = rows.filter(r => r.fee_related === 'issue');
const untagged = feeAll.filter(r => !clean(r.fee_group)).sort((a, b) => String(b.date).localeCompare(String(a.date)));
const stored = feeAll.filter(r => clean(r.fee_group)).map(r => ({ review_id: String(r.review_id), group: clean(r.fee_group) }));
const groups_text = Object.entries(FEE_GROUPS).map(([id, g]) => `${id} ${g.name}: ${g.description}`).join('\n') +
  '\nX Not a charge confusion (price or value complaint, usage limits, feature complaint, not about a ChatGPT/OpenAI charge)';
const fee_text = untagged.length
  ? untagged.map(r => `[${r.review_id}] ${r.rating}★ · label: ${clean(r.fee_type)}\n${cap(`${r.title ?? ''}. ${r.text}`, 80)}`).join('\n\n')
  : '(no new reviews — return {"tags":[]})';
return [{ json: { fee_groups: FEE_GROUPS, groups_text, fee_count: untagged.length,
  fee_ids: untagged.map(r => String(r.review_id)), stored, total_fee_reviews: feeAll.length, fee_text } }];

const list = $('Fee list').first().json;
const G = list.fee_groups;
const rows = $('Load tagged reviews').all().map(i => i.json);
const byId = Object.fromEntries(rows.map(r => [String(r.review_id), r]));
const SOURCE_LABEL = { google_play: 'Google Play', app_store: 'App Store', trustpilot: 'Trustpilot' };
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let aiTags = [];
try { const p = JSON.parse(getText($input.first().json)); aiTags = Array.isArray(p) ? p : (p.tags ?? []); } catch (e) { aiTags = []; }

const newIds = new Set(list.fee_ids), seen = new Set(), problems = [], new_tags = [];
const members = Object.fromEntries(Object.keys(G).map(k => [k, []]));
const excluded = [];
const place = (id, g, reason) => {
  if (g === 'X') { excluded.push({ review_id: id, reason }); return true; }
  if (!G[g]) return false;
  members[g].push(id); return true;
};
for (const s of list.stored) { seen.add(s.review_id); if (!place(s.review_id, s.group.toUpperCase(), 'saved earlier')) problems.push(`bad saved group "${s.group}" for ${s.review_id}`); }
for (const t of aiTags) {
  const id = String(t.review_id ?? '').trim(), g = String(t.group ?? '').trim().toUpperCase();
  if (!newIds.has(id)) { problems.push(`unknown or already-saved id ${id} ignored`); continue; }
  if (seen.has(id)) { problems.push(`id ${id} tagged twice, kept first`); continue; }
  if (!place(id, g, String(t.reason ?? ''))) { problems.push(`unknown group "${g}" for ${id}`); continue; }
  seen.add(id); new_tags.push({ review_id: id, group: g });
}
const unassigned = list.fee_ids.filter(id => !seen.has(id));
if (unassigned.length) problems.push(`${unassigned.length} new fee review(s) not tagged by the AI`);

const pain = r => Math.max(0, 5 - Number(r.rating || 0));
const groups = Object.entries(members).filter(([, ids]) => ids.length).map(([gid, ids]) => {
  const rs = ids.map(id => byId[id]).filter(Boolean);
  return {
    group_id: gid, name: G[gid].name, description: G[gid].description,
    reviews: ids.length, pain_points: rs.reduce((a, r) => a + pain(r), 0),
    newest: rs.map(r => r.date).sort().pop() ?? '',
    sources: [...new Set(rs.map(r => SOURCE_LABEL[r.source] || r.source))],
    review_ids: ids,
  };
}).sort((a, b) => b.reviews - a.reviews || b.pain_points - a.pain_points || b.newest.localeCompare(a.newest));

const PM_PICK = '';
const PM_REASON = 'Close call; refund refusal is also the follow-up complaint in several other fee reviews.';
const closeCall = groups.length > 1 && groups[0].reviews - groups[1].reviews <= 2;
let top = groups[0], selected_by = 'data (most reviews)';
const contenders = groups.filter(g => groups[0].reviews - g.reviews <= 2);
if (closeCall && PM_PICK && contenders.some(g => g.group_id === PM_PICK)) {
  top = groups.find(g => g.group_id === PM_PICK); selected_by = `PM decision on a close call: ${PM_REASON}`;
}
const total = groups.reduce((a, g) => a + g.reviews, 0);
return [{ json: {
  identified_fee_issue: top ? {
    group_id: top.group_id, name: top.name, description: top.description,
    reviews: top.reviews, share_of_confusion_pct: Math.round(1000 * top.reviews / total) / 10,
    sources: top.sources, review_ids: top.review_ids, selected_by,
  } : null,
  rag_query: top ? `${top.name}. ${top.description}` : '',
  groups_ranked: groups.map(({ review_ids, ...g }) => g),
  excluded,
  new_tags,
  fee_check: {
    fee_reviews: list.total_fee_reviews, saved_before: list.stored.length, newly_tagged: new_tags.length,
    in_groups: total, excluded: excluded.length,
    unassigned: unassigned.length, all_accounted_for: unassigned.length === 0 && problems.length === 0, problems,
    clear_winner: !closeCall, close_call: closeCall,
  },
}}];

const rank = $('Rank themes').first().json;
const q = $('Check quotes').first().json.quotes;
const rows = $('Load tagged reviews').all().map(i => i.json);
const MAX_WORDS = 250;
const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const nice = d => { const [y, m, dd] = String(d).split('-'); return `${Number(dd)} ${M[Number(m) - 1]} ${y}`; };
const words = s => String(s).split(/\s+/).filter(Boolean).length;
const runDate = new Date().toISOString().slice(0, 10);
const top = rank.themes_ranked.filter(t => t.top3);
const lc = s => s.charAt(0).toLowerCase() + s.slice(1);

const header = `Weekly Product Pulse: ChatGPT · ${nice(runDate)}\n` +
  `${rank.coverage_eval.total_reviews} reviews · ${nice(rank.window.start)}–${nice(rank.window.end)} · Google Play, App Store, Trustpilot`;
const themesBlock = 'TOP THEMES (by user pain)\n' + top.map((t, i) =>
  `${i + 1}. ${t.name}: ${Math.round(t.share_of_pain_pct)}% of pain, mostly ${lc(t.sub_themes[0].name)}`).join('\n');
const quotesBlock = 'WHAT USERS SAID\n' + q.map(x => `• "${x.quote}" ${x.attribution}`).join('\n');
const playEnd = rows.filter(r => r.source === 'google_play').map(r => r.date).sort().pop();
const moving = rank.trend_google_play.by_theme.filter(t => t.direction === 'rising' || t.direction === 'falling');
const dataNote = 'Data note: ' + (moving.length
  ? moving.map(t => `${t.name} ${t.direction} (Google Play)`).join('; ') + '.'
  : `no reliable trend this week; Google Play data ends ${nice(playEnd)}.`);

const fixedWords = words(header) + words(themesBlock) + words(quotesBlock) + words(dataNote) + 6;
const aiBudget = MAX_WORDS - fixedWords - 5;

const facts = [
  `Top themes ranked by user pain (share of all pain, reviews, average stars, biggest sub-themes):`,
  ...top.map(t => `- ${t.id} ${t.name}: ${t.share_of_pain_pct}% of pain, ${t.reviews} reviews, avg ${t.avg_rating}★. ` +
      `Sub-themes: ${t.sub_themes.slice(0, 3).map(s => `${s.name} (${s.reviews})`).join(', ')}.`),
  `Other themes: ${rank.themes_ranked.filter(t => !t.top3).map(t => `${t.name} ${t.share_of_pain_pct}%`).join(', ')}.`,
  `Praise: ${rank.praise.reviews} reviews (${rank.praise.share_pct}%). Top praise topics: ${rank.praise.top_topics.map(p => `${p.topic} (${p.reviews})`).join(', ')}.`,
  `Verified quotes already shown in the pulse: ${q.map(x => `"${x.quote}"`).join(' | ')}`,
  `Trend: ${dataNote.replace('Data note: ', '')}`,
].join('\n');

return [{ json: {
  run_date: runDate, header, themesBlock, quotesBlock, dataNote,
  top_theme_ids: top.map(t => t.id),
  fixed_words: fixedWords, ai_budget: aiBudget, facts,
  top_themes: top.map(t => `${t.name} (${Math.round(t.share_of_pain_pct)}% of pain)`).join('; '),
}}];

const f = $('Pulse facts').first().json;
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let ai = {};
try { ai = JSON.parse(getText($input.first().json)); } catch (e) { ai = {}; }
const words = s => String(s ?? '').split(/\s+/).filter(Boolean).length;
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();

const obs = clean(ai.key_observation), working = clean(ai.whats_working);
const actions = (ai.actions ?? []).slice(0, 3).map(a => ({ theme_id: String(a.theme_id ?? '').trim(), idea: clean(a.idea) }));

const weekly_pulse = [
  f.header, '', f.themesBlock, '', f.quotesBlock, '',
  `KEY OBSERVATION\n${obs}`, '',
  `WHAT'S WORKING\n${working}`, '',
  'ACTION IDEAS\n' + actions.map((a, i) => `${i + 1}. ${a.idea}`).join('\n'), '',
  f.dataNote,
].join('\n');

const problems = [];
if (!f.facts || !f.ai_budget) problems.push('fact sheet missing: AI wrote without facts');
const total = words(weekly_pulse);
if (total > 250) problems.push(`pulse is ${total} words (max 250)`);
if (!obs) problems.push('key observation missing');
if (!working) problems.push("what's working missing");
if (actions.length !== 3 || actions.some(a => !a.idea)) problems.push('need exactly 3 action ideas');
const covered = new Set(actions.map(a => a.theme_id));
if (!(f.top_theme_ids || []).every(id => covered.has(id))) problems.push('action ideas do not cover all 3 top themes');
const aiText = [obs, working, ...actions.map(a => a.idea)].join(' ');
const factNums = new Set((String(f.facts || '').match(/\d+(\.\d+)?/g) || []));
const newNums = (aiText.match(/\d+(\.\d+)?/g) || []).filter(n => !factNums.has(n));
if (newNums.length) problems.push(`numbers not in the facts: ${[...new Set(newNums)].join(', ')}`);

return [{ json: {
  weekly_pulse,
  top_themes: f.top_themes,
  word_count: total,
  pulse_check: { passed: problems.length === 0, word_count: total, max_words: 250, problems },
}}];

const pages = $('KB pages').all().map(i => i.json);
const out = [], failed = [];
$input.all().forEach((item, idx) => {
  const p = pages[idx];
  const raw = typeof item.json.data === 'string' ? item.json.data : '';
  if (!raw || item.json.error) { failed.push(p.page_name); return; }
  const titleMatch = raw.match(/^Title:\s*(.+)$/m);
  const body = raw.includes('Markdown Content:') ? raw.split('Markdown Content:').slice(1).join(' ') : raw;
  const content = body
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/^[ \t]*[-*=_#]{3,}[ \t]*$/gm, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, 15000);
  if (content.length < 300) { failed.push(`${p.page_name} (too short)`); return; }
  out.push({ json: {
    url: p.url, title: (titleMatch?.[1] || p.page_name).trim(), page_name: p.page_name,
    fetched_at: p.fetched_at, chars: content.length, content,
  }});
});
console.log(`KB: ${out.length} of ${pages.length} pages fetched`, failed.length ? `· failed: ${failed.join(', ')}` : '');
return out;

const issue = $('Pick fee issue').first().json.identified_fee_issue;
const kb = $('KB pages').all().map(i => i.json);
const APPROVED = new Set(kb.map(p => p.url));
const H = 'https://help.openai.com/en/articles/';
const EXPECTED = {
  F1: [H + '7232927-canceling-your-chatgpt-subscription'],
  F2: [H + '7232895-how-do-i-request-a-refund-for-my-chatgpt-subscription'],
  F3: [H + '20001043-how-do-i-avoid-being-charged-twice-if-i-subscribe-to-chatgpt-on-ios-android-and-the-web'],
  F4: [H + '6950777-what-is-chatgpt-plus',
       H + '20001043-how-do-i-avoid-being-charged-twice-if-i-subscribe-to-chatgpt-on-ios-android-and-the-web',
       H + '7242622-why-did-my-chatgpt-plus-or-chatgpt-pro-renewal-transaction-fail'],
  F5: [H + '7232916-why-was-my-credit-card-declined', H + '7242622-why-did-my-chatgpt-plus-or-chatgpt-pro-renewal-transaction-fail'],
  F6: [H + '10421635-multicurrency-billing', H + '8156167-invoice-dates-for-chatgpt-and-api-billing',
       H + '12356340-how-can-i-find-my-past-chatgpt-invoices', H + '9038389-updating-billing-information-tax-id-and-vat-id'],
};
const norm = j => ({ text: String(j.document?.pageContent ?? j.pageContent ?? '').trim(),
                     meta: j.document?.metadata ?? j.metadata ?? {}, score: Number(j.score ?? 0) });
const seen = new Set();
const ranked = $input.all().map(i => norm(i.json))
  .filter(c => c.text && !seen.has(c.text) && seen.add(c.text))
  .sort((a, b) => b.score - a.score);
const pageOrder = [...new Set(ranked.map(c => c.meta.url))];
const expected = EXPECTED[issue?.group_id] ?? [];
const firstExpected = expected.find(u => pageOrder.includes(u));   // expected list is in priority order
// main source = the highest-priority EXPECTED page for this fee issue that retrieval actually found
const topPage = firstExpected || pageOrder[0];
const otherPages = [...pageOrder.filter(u => u !== topPage && expected.includes(u)),   // other expected pages first
                    ...pageOrder.filter(u => u !== topPage && !expected.includes(u))].slice(0, 2);
const stored = $('Store KB').all().map(i => norm(i.json));
const topChunks = stored.filter(c => c.meta.url === topPage).map(c => c.text);
const titleOf = u => (stored.find(c => c.meta.url === u) || ranked.find(c => c.meta.url === u))?.meta.title || u;
const sources = [topPage, ...otherPages].map((u, i) => ({ id: `S${i + 1}`, url: u, title: titleOf(u) }));
const blocks = [
  `[S1 · ${titleOf(topPage)} · full page]\n${topChunks.join('\n')}`,
  ...otherPages.map((u, i) => `[S${i + 2} · ${titleOf(u)} · excerpt]\n${ranked.find(c => c.meta.url === u).text}`),
];
const context_text = blocks.join('\n\n---\n\n');
const links_text = sources.map(s => `${s.id}: ${s.title} — ${s.url}`).join('\n');
const fetched_at = ranked[0]?.meta.fetched_at || kb[0]?.fetched_at;
return [{ json: {
  fee_issue: issue?.name ?? '', fee_issue_description: issue?.description ?? '',
  context_text, links_text,
  allowed_links: sources.map(s => s.url).filter(u => APPROVED.has(u)),
  fetched_at,
  retrieval_check: {
    main_page: titleOf(topPage), main_page_chunks: topChunks.length,
    other_pages: otherPages.map(titleOf), context_chars: context_text.length,
    raw_top_page: titleOf(pageOrder[0]),
    expected_article_found: Boolean(firstExpected),
    expected_page_rank: firstExpected ? pageOrder.indexOf(firstExpected) + 1 : null,
    top_score: Math.round((ranked[0]?.score ?? 0) * 1000) / 1000,
  },
}}];

