const ctx = $('Explainer context').first().json;
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let ai = {};
try { ai = JSON.parse(getText($input.first().json)); } catch (e) { ai = {}; }
const clean = s => String(s ?? '').replace(/\s+/g, ' ').trim();
const words = s => clean(s).split(' ').filter(Boolean).length;
const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const nice = d => { const [y, m, dd] = String(d).split('-'); return `${Number(dd)} ${M[Number(m) - 1]} ${y}`; };

const bullets = (ai.bullets ?? []).map(clean).filter(Boolean);
const links = [...new Set((ai.source_links ?? []).map(u => clean(u)))];
const title = clean(ai.title) || ctx.fee_issue;
const problems = [];

if (!ctx.context_text) problems.push('no retrieved sources: AI wrote without context');
if (bullets.length < 1 || bullets.length > 6) problems.push(`${bullets.length} bullets (allowed 1–6)`);
bullets.forEach((b, i) => { if (words(b) > 35) problems.push(`bullet ${i + 1} has ${words(b)} words (max 35)`); });
if (links.length !== 2) problems.push(`${links.length} source links (need exactly 2)`);
links.forEach(u => { if (!ctx.allowed_links.includes(u)) problems.push(`link not from retrieved official pages: ${u}`); });

const BANNED = [/\bsorry\b/i, /apolog/i, /unfortunately/i, /\bscam\b/i, /\bfraud/i, /guarantee/i,
  /will (be )?refund/i, /will (receive|get) (a |your )?(full )?refund/i, /entitled to a refund/i, /\bwe will\b/i];
const allText = [title, ...bullets].join(' ');
BANNED.forEach(rx => { const m = allText.match(rx); if (m) problems.push(`banned phrase: "${m[0]}"`); });

const srcNums = new Set(ctx.context_text.match(/\d+(\.\d+)?/g) || []);
const bad = [...new Set((bullets.join(' ').match(/\d+(\.\d+)?/g) || []).filter(n => !srcNums.has(n)))];
if (bad.length) problems.push(`numbers not in the sources: ${bad.join(', ')}`);

const last_checked = `Last checked: ${nice(ctx.fetched_at)}`;
const explainer_text = [title, '', ...bullets.map(b => `• ${b}`), '', 'Sources:', ...links.map(u => `- ${u}`), '', last_checked].join('\n');
return [{ json: {
  identified_fee_issue: ctx.fee_issue,
  explainer_title: title,
  explanation_bullets: bullets,
  source_links: links,
  last_checked,
  explainer_text,
  explainer_check: { passed: problems.length === 0, problems, retrieval: ctx.retrieval_check },
}}];

const rank = $('Rank themes').first().json;
const pulse = $('Assemble pulse').first().json;
const facts = $('Pulse facts').first().json;
const q = $('Check quotes').first().json;
const ex = $('Check explainer').first().json;
const fee = $('Pick fee issue').first().json;
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let ai = {}; try { ai = JSON.parse(getText($('Write pulse').first().json)); } catch (e) { ai = {}; }

const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const today = new Date().toISOString().slice(0, 10);
const nice = d => { const [y, m, dd] = String(d).split('-'); return `${Number(dd)} ${M[Number(m) - 1]} ${y}`; };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lc = s => s.charAt(0).toLowerCase() + s.slice(1);
const top = rank.themes_ranked.filter(t => t.top3);
const actions = (ai.actions ?? []).map(a => String(a.idea ?? '').trim()).filter(Boolean);
const fi = fee.identified_fee_issue;
const feeNote = `${fi.reviews} of ${fee.fee_check.in_groups} charge-confusion reviews` + (fee.fee_check.close_call ? ' · close call' : '');
const window = `${nice(rank.window.start)} – ${nice(rank.window.end)}`;

// ---------- 1) DOC ENTRY (plain text, but structured) ----------
const entry_core = [
  `▸ Date (date): ${today}`,
  `▸ Top themes (top_themes):\n` + top.map((t, i) => `   ${i + 1}. ${t.name} — ${Math.round(t.share_of_pain_pct)}% of pain`).join('\n'),
  `▸ Weekly pulse (weekly_pulse):\n\n${pulse.weekly_pulse}`,
  `▸ Identified fee issue (identified_fee_issue): ${fi.name} (${feeNote})`,
  `▸ Customer explainer (explanation_bullets):\n   ${ex.explainer_title}\n` + ex.explanation_bullets.map(b => `   • ${b}`).join('\n'),
  `▸ Sources (source_links):\n` + ex.source_links.map(u => `   • ${u}`).join('\n'),
  `▸ ${ex.last_checked}`,
].join('\n\n');

// ---------- 2) EMAIL DRAFT (HTML, inline styles for Gmail) ----------
const email_subject = `Weekly Product Pulse + Customer Clarification — ${nice(today)}`;
const S = {
  wrap: 'font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#1f2937;max-width:680px',
  h1: 'font-size:20px;margin:0 0 4px', meta: 'color:#6b7280;font-size:12px;margin:0 0 16px',
  h2: 'font-size:16px;margin:24px 0 8px;padding-bottom:4px;border-bottom:2px solid #e5e7eb',
  h3: 'font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:#6b7280;margin:16px 0 6px',
  th: 'text-align:left;padding:6px 8px;background:#f3f4f6;font-size:12px', td: 'padding:6px 8px;border-top:1px solid #e5e7eb;vertical-align:top',
  quote: 'margin:6px 0;padding:6px 10px;border-left:3px solid #9ca3af;background:#f9fafb',
  box: 'padding:10px 12px;background:#eff6ff;border-radius:6px', note: 'color:#6b7280;font-size:12px',
};
const email_body = `<div style="${S.wrap}">
<p>Hi Team,</p>
<p>Here is this week's product pulse and the customer clarification for the top charge confusion.</p>
<h1 style="${S.h1}">Weekly Product Pulse: ChatGPT</h1>
<p style="${S.meta}">${nice(today)} · ${rank.coverage_eval.total_reviews} reviews · ${window} · Google Play, App Store, Trustpilot</p>

<h2 style="${S.h2}">1. Top themes (by user pain)</h2>
<table style="border-collapse:collapse;width:100%">
<tr><th style="${S.th}">#</th><th style="${S.th}">Theme</th><th style="${S.th}">Share of pain</th><th style="${S.th}">Mostly about</th></tr>
${top.map((t, i) => `<tr><td style="${S.td}">${i + 1}</td><td style="${S.td}"><b>${esc(t.name)}</b></td><td style="${S.td}">${Math.round(t.share_of_pain_pct)}%</td><td style="${S.td}">${esc(lc(t.sub_themes[0].name))}</td></tr>`).join('\n')}
</table>

<h3 style="${S.h3}">What users said</h3>
${q.quotes.map(x => `<p style="${S.quote}">“${esc(x.quote)}”<br><span style="${S.note}">${esc(x.theme_name)} · ${esc(x.attribution.replace(/[()]/g, ''))}</span></p>`).join('\n')}

<h3 style="${S.h3}">Key observation</h3>
<p style="${S.box}">${esc(ai.key_observation)}</p>

<h3 style="${S.h3}">What's working</h3>
<p>${esc(ai.whats_working)}</p>

<h3 style="${S.h3}">Action ideas</h3>
<ol>${actions.map(a => `<li>${esc(a)}</li>`).join('')}</ol>
<p style="${S.note}">${esc(facts.dataNote)}</p>

<h2 style="${S.h2}">2. Customer clarification: ${esc(fi.name)}</h2>
<p style="${S.note}">Most common charge confusion this week (${esc(feeNote)}). Customer-facing text, facts only, from official OpenAI help pages.</p>
<p><b>${esc(ex.explainer_title)}</b></p>
<ul>${ex.explanation_bullets.map(b => `<li style="margin-bottom:4px">${esc(b)}</li>`).join('')}</ul>
<p><b>Sources</b><br>${ex.source_links.map(u => `<a href="${esc(u)}">${esc(u)}</a>`).join('<br>')}</p>
<p style="${S.note}">${esc(ex.last_checked)}</p>

<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0 8px">
<p style="${S.note}">Generated by the ChatGPT Review Intelligence workflow and approved by a PM before this draft was created.</p>
</div>`;

// ---------- 3) APPROVAL EMAIL (checks first, then exactly what will be written) ----------
const ok = b => (b ? '✅' : '⚠️');
const checks = [
  `${ok(pulse.pulse_check.passed)} Pulse checks (${pulse.pulse_check.word_count}/250 words) ${pulse.pulse_check.problems.join('; ')}`,
  `${ok(q.quotes_check.all_verified)} Quotes verified word-for-word (${q.quotes_check.verified}/3)`,
  `${ok(fee.fee_check.all_accounted_for)} Fee reviews all accounted for (${fee.fee_check.fee_reviews})${fee.fee_check.close_call ? ' · ⚠️ close call between top fee groups' : ''}`,
  `${ok(ex.explainer_check.passed)} Explainer checks ${ex.explainer_check.problems.join('; ')}`,
  `${ok(ex.explainer_check.retrieval.expected_article_found)} Retrieval eval (expected help article found, rank ${ex.explainer_check.retrieval.expected_page_rank ?? '–'})`,
];
const review_html = `<div style="${S.wrap}">
<h2 style="${S.h2}">Approval needed: Weekly Product Pulse — ${nice(today)}</h2>
<p>Nothing is written to the doc or Gmail until you approve. Use the button at the bottom to Approve or Reject, and add comments.</p>
<h3 style="${S.h3}">Automated checks</h3>${checks.map(c => `<p style="margin:2px 0">${esc(c)}</p>`).join('')}
<h3 style="${S.h3}">Email draft subject</h3><p>${esc(email_subject)}</p>
<h3 style="${S.h3}">Preview of the email draft</h3>
<div style="border:1px solid #e5e7eb;border-radius:6px;padding:12px">${email_body}</div></div>`;

return [{ json: { run_date: today, review_html, entry_core, email_subject, email_body,
  all_checks_passed: pulse.pulse_check.passed && q.quotes_check.all_verified && ex.explainer_check.passed && ex.explainer_check.retrieval.expected_article_found } }];

const prep = $('Prepare review').first().json;
const rank = $('Rank themes').first().json;
const pulse = $('Assemble pulse').first().json;
const facts = $('Pulse facts').first().json;
const q = $('Check quotes').first().json;
const ex = $('Check explainer').first().json;
const fee = $('Pick fee issue').first().json;
const getText = x => x.output?.[0]?.content?.[0]?.text ?? x.text ?? x.message?.content ?? x.content ?? '';
let ai = {}; try { ai = JSON.parse(getText($('Write pulse').first().json)); } catch (e) { ai = {}; }

const j = $input.first().json;
const flat = { ...(j.data ?? {}), ...j };
const find = name => { const k = Object.keys(flat).find(k => k.toLowerCase().includes(name)); return k ? flat[k] : ''; };
const decision = String(find('decision') || (j.data?.approved === true ? 'Approve' : '')).trim();
const approved = /^approve/i.test(decision);
const comments = String(find('comment') || '').trim();
const at = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Kolkata', dateStyle: 'medium', timeStyle: 'short' }) + ' IST';
const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const nice = d => { const [y, m, dd] = String(d).split('-'); return `${Number(dd)} ${M[Number(m) - 1]} ${y}`; };
const lc = s => s.charAt(0).toLowerCase() + s.slice(1);
const runId = $execution.id;
const top = rank.themes_ranked.filter(t => t.top3);
const fi = fee.identified_fee_issue;

const B = [];
B.push({ t: 'h1', text: `Weekly Product Pulse — ${nice(prep.run_date)}` });
B.push({ t: 'p', text: `${approved ? '✅ Approved' : '⛔ Rejected'} by PM · ${at} · Run #${runId}`, gray: true });
if (comments) B.push({ t: 'p', text: `💬 PM comments: ${comments}`, italic: true });
B.push({ t: 'p', text: `Date (date): ${prep.run_date} · ${rank.coverage_eval.total_reviews} reviews · ${nice(rank.window.start)} – ${nice(rank.window.end)} · Google Play, App Store, Trustpilot`, gray: true });

B.push({ t: 'h2', text: 'Top themes (top_themes)' });
top.forEach(t => B.push({ t: 'number', text: `${t.name} — ${Math.round(t.share_of_pain_pct)}% of pain, mostly ${lc(t.sub_themes[0].name)}`, boldPrefix: t.name.length }));

B.push({ t: 'h2', text: 'Weekly pulse (weekly_pulse)' });
B.push({ t: 'h3', text: 'What users said' });
q.quotes.forEach(x => B.push({ t: 'bullet', text: `“${x.quote}” ${x.attribution}`, italic: true }));
B.push({ t: 'h3', text: 'Key observation' });
B.push({ t: 'p', text: String(ai.key_observation ?? '') });
B.push({ t: 'h3', text: "What's working" });
B.push({ t: 'p', text: String(ai.whats_working ?? '') });
B.push({ t: 'h3', text: 'Action ideas' });
(ai.actions ?? []).forEach(a => B.push({ t: 'number', text: String(a.idea ?? '') }));
B.push({ t: 'p', text: facts.dataNote, gray: true });
B.push({ t: 'p', text: `Pulse checks: ${pulse.pulse_check.word_count}/250 words · quotes verified ${q.quotes_check.verified}/3`, gray: true });

B.push({ t: 'h2', text: 'Identified fee issue (identified_fee_issue)' });
B.push({ t: 'p', text: `${fi.name} — ${fi.reviews} of ${fee.fee_check.in_groups} charge-confusion reviews${fee.fee_check.close_call ? ' (close call)' : ''}`, boldPrefix: fi.name.length });

B.push({ t: 'h2', text: 'Customer explainer (explanation_bullets)' });
B.push({ t: 'p', text: ex.explainer_title, bold: true });
ex.explanation_bullets.forEach(b => B.push({ t: 'bullet', text: b }));

B.push({ t: 'h2', text: 'Sources (source_links)' });
ex.source_links.forEach(u => B.push({ t: 'bullet', text: u, link: u }));
B.push({ t: 'p', text: ex.last_checked, gray: true });

const entry_json = JSON.stringify(B);
const entry_text = B.map(b => b.text).join('\n');
return [{ json: { approved, decision: decision || '(no answer)', comments, decided_at: at, run_id: runId,
  entry_json, entry_text, email_subject: prep.email_subject, email_body: prep.email_body } }];

const P = $('Pick fee issue').first().json;
const L = $('Fee list').first().json;
const G = L.fee_groups;
const nameOf = g => g === 'X' ? 'Not a charge confusion' : (G[g]?.name ?? '');
// saved labels (refresh their names) + any new labels from this run
const all = [...L.stored.map(s => ({ review_id: s.review_id, group: s.group.toUpperCase() })), ...P.new_tags];
return all.map(t => ({ json: { review_id: t.review_id, fee_group: t.group, fee_group_name: nameOf(t.group) } }));

const d = $('Read decision').first().json;
return [{ json: { status: 'rejected', decided_at: d.decided_at, comments: d.comments,
  note: 'Rejected by PM: nothing was written to the doc or Gmail.' } }];
